# Let's read the whole context structure by looking at the pattern
# Search for "[turn" 
results = await CONTEXT.search("[turn")
if isinstance(results, dict):
    items = results.get("items", [])
    for item in items[:10]:
        offset = item["offset"]
        snippet = item["snippet"][:300]
        print(f"offset={offset}: {snippet}")
elif isinstance(results, list):
    for r in results[:10]:
        print(str(r)[:300])
